import{_ as o,o as c,c as t,a0 as a}from"./chunks/framework.OED5XGjC.js";const p=JSON.parse('{"title":"Release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),s={name:"explanation/release-model.md"};function d(r,e,i,l,n,h){return c(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="release-model" tabindex="-1">Release model <a class="header-anchor" href="#release-model" aria-label="Permalink to &quot;Release model&quot;">​</a></h1><p>Releases are manual: <code>scripts/release.sh</code> is run by an operator on <code>main</code> — the old trigger (bupha watch on each <code>main</code> push) is retired; CI is now the peregrin <code>ci-gate</code> campaign. The script&#39;s leading debounce window (default 5 min, <code>MYCO_RELEASE_DEBOUNCE</code>) still applies, and it pushes commits and tags to <code>main</code>.</p><h2 id="what-a-release-run-does" tabindex="-1">What a release run does <a class="header-anchor" href="#what-a-release-run-does" aria-label="Permalink to &quot;What a release run does&quot;">​</a></h2><ol><li><strong>Diff since the last tag</strong> — the release set is a <em>fixed</em> list of six crates: <code>myco-core</code>, <code>myco-git</code>, <code>myco-config</code>, <code>myco-config-toml</code>, <code>myco-shell</code>, <code>myco-cli</code>. Only changes under <code>crates/&lt;one-of-those&gt;/</code> count; changes to <code>myco-ops</code>, <code>myco-store*</code>, <code>myco-index*</code>, <code>myco-tui</code>, <code>myco-driver</code>, or <code>myco-testkit</code> trigger nothing. The <code>myco</code> binary re-publishes whenever any of the six changed. No release-set changes, no release.</li><li><strong>Per-crate patch bump + publish</strong> — <code>cargo set-version -p &lt;crate&gt; --bump patch</code>, then <code>cargo publish</code> with retries, in dependency order (<code>myco-core myco-config myco-git myco-shell myco-config-toml myco</code>). Each crate gets its own tag <code>&lt;crate&gt;-v&lt;ver&gt;</code> — versions diverge independently in the monorepo.</li><li><strong>Commit + push</strong> — one <code>release: bump crate versions</code> commit, pushed to <code>main</code> with the tags.</li><li><strong>Binary dist</strong> — when <code>dist</code> and <code>gh</code> are available, a local <code>dist build</code> produces the shell installer (<code>dist-workspace.toml</code>, host arch <code>x86_64-unknown-linux-gnu</code> only — other targets are a TODO for remote workers), uploaded to a GitHub Release <code>myco-v&lt;ver&gt;</code> with generated notes.</li></ol><p>With no tags at all the script exits early — the flow is seeded by tagging once.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>The crates.io name <code>myco</code> is currently held by an unrelated project, so <code>cargo publish</code> of the CLI package depends on resolving that; installs should use <code>cargo install --git https://github.com/9aia/myco</code> regardless.</li><li>Only the six release-set crates publish — the rest of the workspace (<code>myco-ops</code>, <code>myco-store*</code>, <code>myco-index*</code>, <code>myco-tui</code>, <code>myco-driver</code>, <code>myco-testkit</code>) is internal and installs via <code>cargo install --git</code>.</li></ul><h2 id="ci-and-docs-deploys" tabindex="-1">CI and docs deploys <a class="header-anchor" href="#ci-and-docs-deploys" aria-label="Permalink to &quot;CI and docs deploys&quot;">​</a></h2><p>There are no GitHub Actions workflows; the gate is the peregrin <code>ci-gate</code> campaign (bupha watch is retired):</p><ul><li><strong>Push to <code>docs</code></strong> runs <code>scripts/deploy-docs.sh</code>, which rebuilds the site and pushes <code>gh-pages</code> — Pages is a legacy branch deploy, so that push is the whole release of the site.</li><li><strong>Push to <code>main</code></strong> is gated by the ci-gate campaign (<code>scripts/ci.sh</code> = <code>check &amp;&amp; test</code> + the coverage floor) and locally by the <code>pre-push</code> hook (<code>cargo xtask check</code>).</li></ul>',10)])])}const g=o(s,[["render",d]]);export{p as __pageData,g as default};
